// Agility: how quick the player is right now. It is a readout of the body, so this script sets it every turn.
const stamina = owner.stats.Stamina;
const sugar = owner.stats.Sugar;
const traits = owner.traits;

// Energy sets the base. Even an exhausted student can shuffle along, so the base is 30 and full Stamina adds 70.
// Stamina is read as a share of its max, so Star Athlete's bigger tank counts the same when it is full.
const energy = stamina.value / stamina.max;
let agility = 30 + energy * 70;

// Chocolate weighs the legs down: a full stomach costs 40.
// Sugar is read as a share of its max too, so a Sweet Tooth fills up later and a Dainty Appetite sooner.
const fullness = sugar.value / sugar.max;
agility = agility - fullness * 40;

// All-Out Sprint trades Stamina for speed. While it is on, the player gets a burst of 20.
if (traits["All-Out Sprint"].enabled) agility = agility + 20;

// The stat clamps the result to 0–100.
return Math.round(agility);
